// Parity test: the browser demo engine must give the same /match numbers as the Python backend.
// Reference: backend/fixtures/match_golden.json (generated by backend/tools/export_demo_fixtures.py).
//   npm run test:parity
import { build } from "esbuild";
import { readFileSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const golden = JSON.parse(readFileSync(join(here, "../../backend/fixtures/match_golden.json"), "utf8"));

const dir = mkdtempSync(join(tmpdir(), "reloop-parity-"));
const out = join(dir, "engine.mjs");
await build({ entryPoints: [join(here, "../src/demo/engine.ts")], bundle: true, platform: "node", format: "esm", outfile: out, logLevel: "error" });
const { demoMatch } = await import(pathToFileURL(out).href);

const presets = golden.meta.presets;
const close = (a, b) => (a == null || b == null ? a === b : Math.abs(a - b) < 0.011);
const FIELDS = ["quoted_quantity", "missing_quantity", "covers_quantity", "distance_km", "estimated_cost_try", "score",
  "avoided_kgco2e", "avoided_kgco2e_conservative", "transport_kgco2e"];

let fails = 0;
for (const [key, want] of Object.entries(golden.cases)) {
  const [category, preset, start_date, end_date, q] = key.split("|");
  const got = demoMatch({ category, quantity: Number(q), start_date, end_date, location: presets[preset] });
  const problems = [];
  if (got.total_options !== want.total_options) problems.push(`total_options ${got.total_options} != ${want.total_options}`);
  if (got.days !== want.days) problems.push(`days ${got.days} != ${want.days}`);
  // The golden file stores suggestion types only.
  const gotTypes = got.suggestions.map((s) => s.type);
  if (JSON.stringify(gotTypes) !== JSON.stringify(want.suggestions)) problems.push(`suggestions ${gotTypes} != ${want.suggestions}`);
  if (got.matches.length !== want.matches.length) problems.push("match count differs");
  want.matches.forEach((w, i) => {
    const g = got.matches[i];
    if (!g || g.item_id !== w.item_id) return problems.push(`#${i} item ${g?.item_id} != ${w.item_id}`);
    const flat = { ...g, ...g.impact, impact_status: g.impact.status };
    for (const f of FIELDS) if (f in w && !(typeof w[f] === "number" ? close(flat[f], w[f]) : flat[f] === w[f])) problems.push(`#${i} ${f} ${flat[f]} != ${w[f]}`);
    if (w.impact_status !== flat.impact_status) problems.push(`#${i} impact_status`);
  });
  if (problems.length) {
    fails++;
    if (fails <= 10) console.log(`FAIL ${key}: ${problems.slice(0, 4).join("; ")}`);
  }
}
rmSync(dir, { recursive: true, force: true });
const n = Object.keys(golden.cases).length;
console.log(`${n - fails}/${n} golden cases match (backend commit ${golden.meta.backend_commit}).`);
process.exit(fails ? 1 : 0);
